INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich Updates ohne Tests implementieren?', 2, '[{"text": "Nein", "correct": true, "because": "Tests sichern Stabilität"}, {"text": "Ja", "correct": false, "because": "Risiko für Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Updates und Patches?', 3, '[{"text": "Sicherheit erhöhen", "correct": true, "because": "Schließt Schwachstellen"}, {"text": "UI-Design", "correct": false, "because": "Anderer Fokus"}, {"text": "Marketing", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Patch-Implementierung?', 5, '[{"text": "Testen", "correct": true, "because": "Verifiziert Funktion"}, {"text": "Bereitstellung", "correct": true, "because": "Rollt Patch aus"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Zu zeitaufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Patches schließen Sicherheitslücken. b) Updates sind immer optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Update-Implementierung?', 4, '[{"text": "Testumgebung", "correct": false, "because": "Sichert Stabilität"}, {"text": "Changelog", "correct": false, "because": "Zeigt Änderungen"}, {"text": "Schriftgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Patches immer Bugfixes sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Sicherheitsupdates"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für Patch-Management?', 3, '[{"text": "WSUS", "correct": true, "because": "Verwaltet Updates"}, {"text": "Notepad", "correct": false, "because": "Unpraktisch"}, {"text": "E-Mail", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Patch-Implementierung effektiv?', 5, '[{"text": "Priorisierung", "correct": true, "because": "Wichtige Fixes zuerst"}, {"text": "Automatisierung", "correct": true, "because": "Spart Zeit"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}, {"text": "Lange Wartezeiten", "correct": false, "because": "Verzögert Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Updates sind nur für Sicherheit. b) Tests sind überflüssig. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) auch Funktionen, b) nötig"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) unvollständig"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Patch-Implementierung?', 4, '[{"text": "Testsystem", "correct": false, "because": "Prüft Stabilität"}, {"text": "Rollback-Plan", "correct": false, "because": "Sichert Rückkehr"}, {"text": "Teamfotos", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Updates immer sofort umsetzbar?', 2, '[{"text": "Nein", "correct": true, "because": "Tests nötig"}, {"text": "Ja", "correct": false, "because": "Risiko ohne Prüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Infos sind bei der Implementierung entscheidend?', 4, '[{"text": "Changelog", "correct": true, "because": "Zeigt Änderungen"}, {"text": "Testprotokolle", "correct": true, "because": "Bestätigt Funktion"}, {"text": "UI-Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Patches automatisch sicher sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Tests erforderlich"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Patch-Implementierung?', 3, '[{"text": "Sicherheitslücken", "correct": true, "because": "Schutz hat Vorrang"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}, {"text": "Kleinere Fixes", "correct": false, "because": "Weniger dringend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tests prüfen Stabilität. b) Updates brauchen keine Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) erfordert Planung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Patch-Implementierung?', 5, '[{"text": "Sicherheitsgewinn", "correct": true, "because": "Schließt Lücken"}, {"text": "Stabilität", "correct": true, "because": "Verhindert Abstürze"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Implementierung unwichtig?', 3, '[{"text": "Testphase", "correct": false, "because": "Sichert Funktion"}, {"text": "Priorität", "correct": false, "because": "Fokussiert Dringlichkeit"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Patches die Wartung?', 3, '[{"text": "Nein", "correct": true, "because": "Teil der Wartung"}, {"text": "Ja", "correct": false, "because": "Wartung breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Updates immer Funktionen bringen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Bugfixes, Sicherheit"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für die Implementierung entscheidend?', 4, '[{"text": "Rollback", "correct": true, "because": "Sichert Rückkehr bei Fehlern"}, {"text": "Hohe Komplexität", "correct": false, "because": "Verwirrt"}, {"text": "Manuelle Eingriffe", "correct": false, "because": "Ineffizient"}]');
